import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { id3Schema, type Id3 } from "./unions/id3.js";
import { outputSchema, type Output } from "./unions/output.js";
import { status1Schema, type Status1 } from "./unions/status1.js";

export type ResponsesFunctionCallOutput = {
  /**
   * The type of the function tool call output. Always `function_call_output`.
   *
   * @default "function_call_output"
   */
  type?: "function_call_output";
  /** The unique ID of the function tool call generated by the model. */
  callId: string;
  /**
   * Text or image output of the function tool call. Can be a JSON string of the output, or an array
   * of content parts (text or image).
   */
  output: Output;
  /** The unique ID of the function tool call output. */
  id?: Id3;
  /** The status of the item. One of `in_progress`, `completed`, or `incomplete`. */
  status?: Status1;
};

export const responsesFunctionCallOutputSchema: Schema<ResponsesFunctionCallOutput> =
  s.object<ResponsesFunctionCallOutput>({
    type: s.defaulted(s.literal("function_call_output"), "function_call_output"),
    callId: s.string(),
    output: outputSchema,
    id: s.optional(s.lazy(() => id3Schema)),
    status: s.optional(s.lazy(() => status1Schema)),
    _keysMap: {
      callId: "call_id",
    },
  });
